//! Two generated files, both checked in and rewritten only when their inputs
//! change:
//!
//! - `src/drivers/generated_registry.rs` — the driver dispatch table, from the
//!   `src/drivers/*.rs` modules.
//! - `src/components/generated_vocab.rs` — the bus-component tags and their
//!   required attributes, from the one element schema
//!   (`espforge-espgenerate-template/src/espf.schema.kdl`).

use std::fs;
use std::path::Path;

fn main() {
    drivers();
    component_vocab();
}

/// The driver registry: one dispatch arm per `src/drivers/*.rs` module.
fn drivers() {
    println!("cargo:rerun-if-changed=src/drivers");

    let drivers_dir = Path::new("src/drivers");
    let dest_path = Path::new("src/drivers/generated_registry.rs");

    let mut modules = Vec::new();
    let mut match_arms = Vec::new();
    let mut tags = Vec::new();

    if let Ok(entries) = fs::read_dir(drivers_dir) {
        for entry in entries.flatten() {
            let path = entry.path();
            println!("cargo:rerun-if-changed={}", path.display());
            if path.extension().map_or(false, |ext| ext == "rs") {
                let stem = path.file_stem().unwrap().to_str().unwrap().to_string();
                if stem != "mod" && stem != "generated_registry" {
                    // #[path] is relative to src/drivers/ (the directory containing
                    // generated_registry.rs), so "tmp102.rs" resolves to
                    // src/drivers/tmp102.rs. Do not remove.
                    modules.push(format!(
                        "#[path = \"{stem}.rs\"]\npub mod {stem};"
                    ));
                    match_arms.push(format!(
                        "        \"{stem}\" => {stem}::init(device, ctx),"
                    ));
                    tags.push(format!("\"{stem}\""));
                }
            }
        }
    }

    let generated_code = format!(
        "// AUTO-GENERATED BY BUILD.RS - DO NOT EDIT MANUALLY\n\n\
        #[allow(dead_code)]\n\
        {}\n\n\
        /// The device tags this registry routes, emitted alongside `route_driver`\n\
        /// so the `espforge espf` catalog can be drift-checked against it.\n\
        pub const TAGS: &[&str] = &[{}];\n\
        \n\
        pub fn route_driver(tag_name: &str, device: &espf::context::ResolvedDevice, ctx: &espf::context::RuntimeContext) -> Result<(), String> {{\n\
            match tag_name {{\n\
        {}\n\
                _ => Err(format!(\"❌ No compile-time driver engine found for runtime tag <{{}}>\", tag_name)),\n\
            }}\n\
        }}",
        modules.join("\n"),
        tags.join(", "),
        match_arms.join("\n")
    );

    write_if_changed(dest_path, &generated_code);
}

/// The bus-component vocabulary, read from the single element schema.
///
/// A "bus component" is an element in the schema's `components` section that
/// has a `ref` attribute to a peripheral (`gpio`, `i2c`, `spi`, `uart`). Its
/// required attributes — minus `id`, which every element has — are what the
/// catalog renders and what the drift tests used to compare against the
/// wrappers by hand. Generating them removes the comparison.
fn component_vocab() {
    const SCHEMA: &str = "../espforge-espgenerate-template/src/espf.schema.kdl";
    println!("cargo:rerun-if-changed={SCHEMA}");

    let src = fs::read_to_string(SCHEMA)
        .unwrap_or_else(|e| panic!("cannot read {SCHEMA}: {e}"));
    let doc = kdl::KdlDocument::parse_v2(&src)
        .unwrap_or_else(|e| panic!("{SCHEMA} is not valid KDL v2:\n{e}"));

    // (tag, required attributes besides `id`)
    let mut components: Vec<(String, Vec<String>)> = Vec::new();

    for node in doc.nodes() {
        if node.name().value() != "element" {
            continue;
        }
        let section = node.get("section").and_then(|value| value.as_string());
        if section != Some("components") {
            continue;
        }
        let tag = node
            .entries()
            .iter()
            .find(|entry| entry.name().is_none())
            .and_then(|entry| entry.value().as_string())
            .unwrap_or_else(|| panic!("an `element` in {SCHEMA} has no tag name"));

        let mut required = Vec::new();
        let mut has_peripheral_ref = false;
        for attr in node.children().map(|children| children.nodes()).unwrap_or_default() {
            if attr.name().value() != "attr" {
                continue;
            }
            let name = attr
                .entries()
                .iter()
                .find(|entry| entry.name().is_none())
                .and_then(|entry| entry.value().as_string())
                .unwrap_or_else(|| panic!("an `attr` of `{tag}` in {SCHEMA} has no name"));
            if attr.get("kind").and_then(|value| value.as_string()) == Some("ref") {
                has_peripheral_ref = true;
            }
            let is_required = attr
                .get("required")
                .and_then(|value| value.as_bool())
                .unwrap_or(false);
            if is_required && name != "id" {
                required.push(name.to_string());
            }
        }

        if has_peripheral_ref {
            components.push((tag.to_string(), required));
        }
    }

    let mut out = String::from(
        "// AUTO-GENERATED BY BUILD.RS FROM espf.schema.kdl - DO NOT EDIT MANUALLY\n\n",
    );
    out.push_str(
        "/// The `<*_component>` tags that bind a peripheral, in schema order.\n\
         ///\n\
         /// Read from the `components` section of `espf.schema.kdl`, so the\n\
         /// catalog, the wrappers and this table cannot disagree.\n",
    );
    let tags: Vec<String> = components
        .iter()
        .map(|(tag, _)| format!("\"{tag}\""))
        .collect();
    out.push_str(&format!(
        "pub const TAGS: &[&str] = &[{}];\n\n",
        tags.join(", ")
    ));

    for (tag, required) in &components {
        let required: Vec<String> = required.iter().map(|a| format!("\"{a}\"")).collect();
        out.push_str(&format!(
            "/// Required attributes of `<{tag}>` besides `id`.\npub const {}: &[&str] = &[{}];\n\n",
            const_name(tag),
            required.join(", ")
        ));
    }

    out.push_str(
        "/// Required attributes of a bus component tag besides `id`.\n\
         pub fn required_attrs(tag: &str) -> Option<&'static [&'static str]> {\n\
         \x20   match tag {\n",
    );
    for (tag, _) in &components {
        out.push_str(&format!(
            "        \"{tag}\" => Some({}),\n",
            const_name(tag)
        ));
    }
    out.push_str("        _ => None,\n    }\n}\n");

    write_if_changed(Path::new("src/components/generated_vocab.rs"), &out);
}

/// `i2c_component` -> `I2C_COMPONENT`, for the generated const names.
fn const_name(tag: &str) -> String {
    tag.chars()
        .map(|c| {
            if c.is_ascii_alphanumeric() {
                c.to_ascii_uppercase()
            } else {
                '_'
            }
        })
        .collect()
}

/// Keep the checked-in file and the generated one identical, without touching
/// the file (and its mtime) when nothing changed.
fn write_if_changed(path: &Path, contents: &str) {
    let current = fs::read_to_string(path).unwrap_or_default();
    if current != contents {
        fs::write(path, contents).unwrap_or_else(|e| panic!("cannot write {}: {e}", path.display()));
    }
}
